const inventory = $('Inventario').first().json.results || $('Inventario').first().json.data || [];
const sales = $('Ventas').first().json.results || $('Ventas').first().json.data || [];

const now = new Date();
const dayMs = 86400000;

// Parsear inventario
const books = inventory.map(book => {
  const p = book.properties || {};
  return {
    pageId: book.id,
    title: p.Nombre?.title?.[0]?.plain_text || '',
    author: p.Autor?.rich_text?.[0]?.plain_text || '',
    genre: p.Genero?.select?.name || 'Otros',
    estadoPublicacion: p['Estado publicacion']?.select?.name || '',
    coste: p.Coste?.number || 0,
    precioVenta: p['Precio venta']?.number || 0,
    fechaEntrada: p['date:Fecha entrada:start'] || '',
    sku: p.SKU?.number || p.SKU?.formula_string || '',
    marketingGenerado: p['Marketing generado'] === '__YES__'
  };
});

// Genero mas vendido (para promocion)
const generoCount = {};
sales.forEach(s => {
  const p = s.properties || {};
  const g = p.Genero?.select?.name;
  if (g) generoCount[g] = (generoCount[g] || 0) + 1;
});
const topGenero = Object.entries(generoCount).sort((a,b) => b[1] - a[1])[0];
const topGeneroName = topGenero ? topGenero[0] : null;

// Solo libros publicados
const disponibles = books.filter(b => b.estadoPublicacion === 'Publicado');

const recomendaciones = [];

for (const book of disponibles) {
  if (!book.fechaEntrada) continue;

  const diasEnStock = Math.floor((now - new Date(book.fechaEntrada)) / dayMs);
  const margenEur = book.precioVenta - book.coste;
  const margenPct = book.precioVenta > 0 ? (margenEur / book.precioVenta) * 100 : 0;
  const precioMinimo = book.coste * 1.5; // Margen minimo del 50%

  // REGLA 1: Libro parado +90 dias -> rebajar 20%
  if (diasEnStock > 90) {
    let precioSugerido = Math.round((book.precioVenta * 0.8) * 100) / 100;
    if (precioSugerido < precioMinimo) precioSugerido = Math.round(precioMinimo * 100) / 100;

    recomendaciones.push({
      titulo: `${book.title} - Rebaja +90 dias`,
      tipo: 'Rebaja',
      sku: String(book.sku),
      libro: book.title,
      autor: book.author,
      genero: book.genre,
      precioActual: book.precioVenta,
      precioSugerido: precioSugerido,
      motivo: `Libro en stock ${diasEnStock} dias sin vender. Rebaja del 20%. Precio minimo: ${precioMinimo.toFixed(2)} eur (margen 50%).`,
      confianza: 'Alta',
      accion: 'Rebajar',
      estado: 'Pendiente',
      fecha: now.toISOString().split('T')[0],
      pageId: book.pageId
    });
  }
  // REGLA 2: Libro parado +60 dias -> rebajar 10%
  else if (diasEnStock > 60) {
    let precioSugerido = Math.round((book.precioVenta * 0.9) * 100) / 100;
    if (precioSugerido < precioMinimo) precioSugerido = Math.round(precioMinimo * 100) / 100;

    recomendaciones.push({
      titulo: `${book.title} - Rebaja +60 dias`,
      tipo: 'Rebaja',
      sku: String(book.sku),
      libro: book.title,
      autor: book.author,
      genero: book.genre,
      precioActual: book.precioVenta,
      precioSugerido: precioSugerido,
      motivo: `Libro en stock ${diasEnStock} dias sin vender. Rebaja del 10%. Precio minimo: ${precioMinimo.toFixed(2)} eur.`,
      confianza: 'Media',
      accion: 'Rebajar',
      estado: 'Pendiente',
      fecha: now.toISOString().split('T')[0],
      pageId: book.pageId
    });
  }
  // REGLA 3: Libro parado +30 dias -> promocionar
  else if (diasEnStock > 30) {
    if (book.marketingGenerado) {
      recomendaciones.push({
        titulo: `${book.title} - Promocion +30 dias`,
        tipo: 'Promocion',
        sku: String(book.sku),
        libro: book.title,
        autor: book.author,
        genero: book.genre,
        precioActual: book.precioVenta,
        precioSugerido: book.precioVenta,
        motivo: `Libro en stock ${diasEnStock} dias. Marketing ya generado. Sugerencia: destacar en redes o newsletter.`,
        confianza: 'Media',
        accion: 'Promocionar',
        estado: 'Pendiente',
        fecha: now.toISOString().split('T')[0],
        pageId: book.pageId
      });
    } else {
      recomendaciones.push({
        titulo: `${book.title} - Generar marketing`,
        tipo: 'Promocion',
        sku: String(book.sku),
        libro: book.title,
        autor: book.author,
        genero: book.genre,
        precioActual: book.precioVenta,
        precioSugerido: book.precioVenta,
        motivo: `Libro en stock ${diasEnStock} dias sin marketing generado. Generar copy y publicar en redes.`,
        confianza: 'Alta',
        accion: 'Promocionar',
        estado: 'Pendiente',
        fecha: now.toISOString().split('T')[0],
        pageId: book.pageId
      });
    }
  }
  // REGLA 4: Genero top en ventas -> promocionar libros de ese genero
  if (topGeneroName && book.genre === topGeneroName && diasEnStock < 30 && margenPct > 60) {
    recomendaciones.push({
      titulo: `${book.title} - Destacar (genero top)`,
      tipo: 'Promocion',
      sku: String(book.sku),
      libro: book.title,
      autor: book.author,
      genero: book.genre,
      precioActual: book.precioVenta,
      precioSugerido: book.precioVenta,
      motivo: `Genero "${book.genre}" es el mas vendido (${topGenero[1]} ventas). Margen alto (${margenPct.toFixed(0)}%). Destacar en proxima newsletter.`,
      confianza: 'Alta',
      accion: 'Promocionar',
      estado: 'Pendiente',
      fecha: now.toISOString().split('T')[0],
      pageId: book.pageId
    });
  }
  // REGLA 5: Margen bajo -> revisar precio
  if (margenPct < 40 && book.precioVenta > 0) {
    let precioSugerido = Math.round((book.coste * 2) * 100) / 100;
    recomendaciones.push({
      titulo: `${book.title} - Margen bajo`,
      tipo: 'Precio',
      sku: String(book.sku),
      libro: book.title,
      autor: book.author,
      genero: book.genre,
      precioActual: book.precioVenta,
      precioSugerido: precioSugerido,
      motivo: `Margen actual: ${margenPct.toFixed(0)}%. Precio sugerido: ${precioSugerido} eur (margen 100%). Revisar si el precio de venta es competitivo.`,
      confianza: 'Media',
      accion: 'Revisar',
      estado: 'Pendiente',
      fecha: now.toISOString().split('T')[0],
      pageId: book.pageId
    });
  }
  // REGLA 6: Margen muy alto -> posible subida de precio
  if (margenPct > 150 && book.precioVenta > 0 && diasEnStock < 15) {
    let precioSugerido = Math.round((book.precioVenta * 1.1) * 100) / 100;
    recomendaciones.push({
      titulo: `${book.title} - Posible subida`,
      tipo: 'Precio',
      sku: String(book.sku),
      libro: book.title,
      autor: book.author,
      genero: book.genre,
      precioActual: book.precioVenta,
      precioSugerido: precioSugerido,
      motivo: `Margen muy alto (${margenPct.toFixed(0)}%) y venta reciente. Subir 10% a ${precioSugerido} eur puede maximizar beneficio.`,
      confianza: 'Baja',
      accion: 'Revisar',
      estado: 'Pendiente',
      fecha: now.toISOString().split('T')[0],
      pageId: book.pageId
    });
  }
}

// Si no hay recomendaciones
if (recomendaciones.length === 0) {
  return [{ json: { noRecomendaciones: true, message: 'No hay recomendaciones de precio esta semana. Todo el inventario esta en buen estado.' } }];
}

return recomendaciones.map(r => ({ json: r }));

const allRecs = $('Calcular Recomendaciones').all().map(r => r.json).filter(r => !r.noRecomendaciones);

const rebajas = allRecs.filter(r => r.tipo === 'Rebaja');
const promociones = allRecs.filter(r => r.tipo === 'Promocion');
const precios = allRecs.filter(r => r.tipo === 'Precio');

return [{
  json: {
    total: allRecs.length,
    rebajas: rebajas.length,
    promociones: promociones.length,
    precios: precios.length,
    detalle: allRecs.map(r => `- ${r.titulo}: ${r.accion} (confianza: ${r.confianza})`).join('\n'),
    fecha: new Date().toISOString().split('T')[0]
  }
}];

